{
    $config=\Kulturhus\Native\TestSupport::config();if(($config['owner']??null)!=='isolated-native-ci'||!in_array($config['label']??null,['native-transfer-interface','native-payment-returns','native-return-order-links','native-transfer-settlements','native-recovery'],true)||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new RuntimeException('Owned native transfer contracts required.');
    $club='own-transfer-native';$admin='own-transfer-admin';$actor='own-transfer-finance';$key=static fn():string=>bin2hex(random_bytes(16));
    $db->exec("INSERT INTO clubs VALUES('own-transfer-native','Own original transfer association'),('own-transfer-foreign','Own foreign transfer association');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-transfer-admin','own-transfer-native','members',1),('own-transfer-finance','own-transfer-native','treasurer',0),('own-transfer-writer','own-transfer-native','treasurer',0),('own-transfer-reader','own-transfer-native','member',0),('own-transfer-general','own-transfer-native','members',0),('own-transfer-editor','own-transfer-native','editor',1),('own-transfer-foreign','own-transfer-foreign','members',1);INSERT INTO contacts(id,club_id,kind,name)VALUES('own-transfer-supplier','own-transfer-native','organisation','Own actual supplier');INSERT INTO admission_board VALUES('own-transfer-native','own-transfer-finance','Kassenwart',1,1);INSERT INTO admission_board_checks VALUES('own-transfer-native','own-transfer-finance',1,'Kassenwart','own-transfer-admin','2026-10-01')");
    $settings=new Settings($db,$admin);$financeRoleData=['name'=>'Own transfer finance only','members_access'=>'none','finance_access'=>'write','settings_access'=>false];$financeRole=$settings->saveRole('',0,$financeRoleData);foreach([$actor,'own-transfer-writer']as$id)$settings->assignRole($id,$financeRole,0);$readerRole=$settings->saveRole('',0,array_replace($financeRoleData,['name'=>'Own transfer read only','finance_access'=>'read']));$settings->assignRole('own-transfer-reader',$readerRole,0);$generalRole=$settings->saveRole('',0,['name'=>'Own transfer general only','members_access'=>'none','finance_access'=>'none','settings_access'=>true]);$settings->assignRole('own-transfer-general',$generalRole,0);
    $finance=new Finance($db,$actor);$account=$finance->createAccount('Own actual transfer bank','offline','0','2020-01-01');$finance->saveAccountSettings($account,0,true,'',true,true);$settings->save('bank',array_replace(SettingsSchema::defaults('bank'),['account_id'=>$account,'holder'=>'Own original transfer association','iban'=>'DE89370400440532013000','bic'=>'COBADEFFXXX']),0);
