    $path=$existingBankKey??dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/own-native-transfer-bank.key';if($existingBankKey===null){file_put_contents($path,random_bytes(32));chmod($path,0600);}elseif(!is_file($path)||is_link($path)||filesize($path)!==32)throw new RuntimeException('Exact existing installed own bank key required.');putenv('VEREIN_MEMBER_BANK_KEY_PATH='.$path);$keyHash=hash_file('sha256',$path);$vault=new MemberBankVault($db,$actor,$path);$native=new TransferRequests($db,$actor,$vault);$service=new TransferOrders($db,$actor,$vault);$today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');$date=(new DateTimeImmutable($today,new DateTimeZone('Europe/Berlin')))->modify('+1 day')->format('Y-m-d');if($executionToday)$date=$today;
    $entry=static function(string $label='Own genuine native supplier invoice',string $amount='125.50')use($db,$club,$actor,$finance,$pdf,$key,$today):array{
        $id=$finance->createEntry(['kind'=>'expense','description'=>$label,'counterparty'=>'Own actual supplier','amount'=>$amount,'category'=>'inventory','document_date'=>$today,'due_date'=>$today,'notes'=>"Own complete original notes\n0 🙂"],$key());$contact=Db::run($db,'SELECT version FROM contacts WHERE club_id=? AND id=?',[$club,'own-transfer-supplier'])->fetchColumn();Db::run($db,'INSERT INTO finance_supplier_contacts VALUES(?,?,?,?,?,?,?)',[$club,$id,'own-transfer-supplier',(int)$contact,'Own actual supplier',$actor,gmdate('c')]);$bytes=$pdf('transfer '.substr($id,0,12));$document=(new Documents($db,$actor))->upload('own-invoice.pdf',$bytes,['title'=>$label,'kind'=>'invoice','scope'=>'finance','links'=>['entry:'.$id]],$key());$approval=new InvoiceApprovals($db,$actor);$state=$approval->state($id);$approval->approve($id,$state['hash'],$state['decision_id'],$key(),true);return ['entry'=>$id,'document'=>$document,'bytes'=>$bytes,'file_sha256'=>hash('sha256',$bytes),'original_entry'=>$finance->entry($id)];
    };
    $inputFor=static function(string $id,string $mode='standard')use($account,$date,$today):array{$input=TransferInput::initial($id);$input['data']=array_replace($input['data'],['account'=>$account,'execution_date'=>$mode==='instant'?$today:$date,'purpose'=>'Own reviewed supplier invoice','transfer_mode'=>$mode,'reason'=>"\n0 <b>literal original reason</b> 🙂",'evidence'=>"Own actual local invoice review\n0"]);return $input;};
    $deny=static function(callable $work,int $code,string $label)use($check):void{try{$work();}catch(DomainException $failure){$check($failure->getCode()===$code,$label);return;}throw new RuntimeException('Expected native transfer denial: '.$label);};
    $check(Permissions::actor($db,$actor)['members_access']==='none'&&!(new Settings($db,$actor))->canManage(),'actual transfer payment author has Finance writing without member administration or General access');
    $assets=\Kulturhus\Verein\ManagerPageAssets::manifest();$check(($assets['transfer-native.css']['kind']??null)==='style','actual manager navigation registers the scoped transfer stylesheet for safe original-history navigation');
    $tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$invoice=$entry();$input=$inputFor($invoice['entry']);
    foreach(["\n0\n",str_repeat('🙂',1001)]as$whole){$raw=$input;$raw['data']['execution_date']=$whole;$check(TransferInput::capture($raw)===$raw,'whole transfer capture preserves invalid leading LF zero and Unicode for explicit validation');}
    foreach(['0','2026-02-30']as$bad){$raw=$input;$raw['data']['execution_date']=$bad;$deny(fn()=>TransferInput::normalize($raw),422,'impossible transfer calendar remains an error instead of changing the date');}
    $raw=$input;$raw['data']['transfer_mode']='0';$check(TransferInput::capture($raw)===$raw,'whole transfer capture retains the unknown zero payment type');$deny(fn()=>TransferInput::normalize($raw),422,'unknown payment type is never changed to a normal transfer');
    $session=[];$draft=TransferDraft::open($session,Permissions::actor($db,$actor),$input);$check(TransferDraft::get($session,Permissions::actor($db,$actor),$invoice['entry'],'',$draft['id'])===$draft,'personal transfer draft retains the entire exact intention');$deny(fn()=>TransferDraft::get($session,Permissions::actor($db,'own-transfer-writer'),$invoice['entry'],'',$draft['id']),404,'another finance writer cannot inherit the personal transfer draft');TransferDraft::discard($session,$draft);
    $before=ownOriginalDatabaseHash($db,$tables);$review=$native->prepare($input);$check($native->prepare($input)===$review&&ownOriginalDatabaseHash($db,$tables)===$before,'actual whole transfer previews preserve every complete earlier business row');$deny(fn()=>$native->accept($input,$key(),$review['hash'],false),422,'missing independent consent creates no transfer or personal first');
    foreach(['own-transfer-reader','own-transfer-general']as$other)$deny(fn()=>(new TransferRequests($db,$other,new MemberBankVault($db,$other,$path)))->prepare($input),403,'new transfer needs current finance writing for '.$other);
    $db->exec("CREATE TRIGGER own_transfer_first_abort BEFORE INSERT ON native_settings_requests FOR EACH ROW BEGIN IF NEW.section='transfer-order' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Own transfer first abort';END IF;END");$db->beginTransaction();
    try{Db::run($db,'UPDATE clubs SET name=? WHERE id=?',['Own retained earlier caller work','own-list-club']);$earlier=ownOriginalDatabaseHash($db,$tables);$failed=false;try{$native->accept($input,$key(),$review['hash'],true);}catch(PDOException $failure){if(($failure->errorInfo[0]??null)!=='45000')throw $failure;$failed=true;}$check($failed&&$db->inTransaction()&&ownOriginalDatabaseHash($db,$tables)===$earlier,'actual SQL failure after encrypted transfer creation rolls back the whole inner decision and preserves earlier caller work');}
    finally{if($db->inTransaction())$db->rollBack();$db->exec('DROP TRIGGER own_transfer_first_abort');}
    $check(ownOriginalDatabaseHash($db,$tables)===$before,'failed transfer decision preserves every whole original row');
    $first=$native->accept($input,$key(),$review['hash'],true);$order=$first['result']['order']['id'];$firsts=[$first];$after=ownOriginalDatabaseHash($db,$tables);$check($native->accept($input,$first['key'],$review['hash'],true)===$first&&$native->receipt($first['key'])===$first&&ownOriginalDatabaseHash($db,$tables)===$after,'exact accepted transfer replay returns the first original without a second order or row');$deny(fn()=>$native->prepare($input),409,'genuine active transfer prevents preparing a second payment order');
    $check(!str_contains($first['original_json'],'DE89370400440532013000')&&!str_contains($first['original_json'],'DE12500105170648489890')&&!str_contains($first['original_json'],'<Document')&&!isset($first['result']['order']['sealed_snapshot'],$first['result']['order']['snapshot']),'personal transfer first contains neither automatic full bank accounts nor XML nor encrypted bank envelope');
    foreach(['own-transfer-writer'=>404,'own-transfer-reader'=>404,'own-transfer-general'=>403,'own-transfer-foreign'=>404]as$other=>$code)$deny(fn()=>(new TransferRequests($db,$other,new MemberBankVault($db,$other,$path)))->receipt($first['key']),$code,'another actor cannot read the known personal transfer first '.$other);
    foreach(['approve','export','submitted']as$operation){$next=TransferInput::initial($invoice['entry'],$order);$next['operation']=$operation;$next['data']['reason']='Own actual '.$operation.' review';if($operation==='submitted'){$next['data']['bank_reference']='OWN-LOCAL-TRANSFER-ACK';$next['data']['evidence']='Controlled own local evidence; no real bank request';}$prepared=$native->prepare($next);$current=$native->accept($next,$key(),$prepared['hash'],true);$firsts[]=$current;$check($current['result']['order']['state']===['approve'=>'approved','export'=>'exported','submitted'=>'submitted'][$operation],'actual conscious transfer '.$operation.' reaches its own canonical state');if($operation==='export')$check($native->xml($current['key'])===$service->get($order)['snapshot']['xml'],'native exported transfer XML matches the exact encrypted XSD-qualified bank original');}
    $check($native->receipt($first['key'])===$first&&$finance->entry($invoice['entry'])===$invoice['original_entry']&&(new Documents($db,$actor))->file($invoice['document'])['bytes']===$invoice['bytes']&&$finance->transactions()===[],'all transfer decisions preserve the very first receipt, whole original invoice and PDF and book no money');
    $downgrade=$settings->saveRole('',0,array_replace($financeRoleData,['name'=>'Own temporary transfer read only','finance_access'=>'read']));$settings->assignRole($actor,$downgrade,1);$check($native->accept($input,$first['key'],$review['hash'],true)===$first,'own accepted transfer replay remains exact after current downgrade to Finance reading');$deny(fn()=>$native->xml($firsts[2]['key']),403,'historical raw bank XML still needs current payment writing authority');$settings->assignRole($actor,$financeRole,2);
    $writerInvoice=$entry('Own writer-only supplier preparation');$writerInput=$inputFor($writerInvoice['entry']);$writer=new TransferRequests($db,'own-transfer-writer',new MemberBankVault($db,'own-transfer-writer',$path));$writerReview=$writer->prepare($writerInput);$writerFirst=$writer->accept($writerInput,$key(),$writerReview['hash'],true);$next=TransferInput::initial($writerInvoice['entry'],$writerFirst['result']['order']['id']);$next['operation']='approve';$next['data']['reason']='Own denied office approval';$deny(fn()=>$writer->prepare($next),403,'finance writer may prepare but cannot approve a bank order without the confirmed payment office');$next['operation']='cancel';$writerCancel=$writer->prepare($next);$check($writer->accept($next,$key(),$writerCancel['hash'],true)['result']['order']['state']==='cancelled','finance writer can consciously discard the still-unexported own prepared order');
    $clock=new ReflectionMethod(TransferOrders::class,'today');$check($clock->invoke(null,new DateTimeImmutable('2026-10-24T22:30:00Z'))==='2026-10-25'&&$clock->invoke(null,new DateTimeImmutable('2026-10-25T23:30:00Z'))==='2026-10-26','actual bank execution day follows Berlin across the autumn clock change');
    $check(hash_file('sha256',$path)===$keyHash&&$finance->transactions()===[],'whole native transfer contracts preserve the actual bank key and create no money movements');
    return compact('club','admin','actor','account','path','keyHash','native','service','today','date','entry','inputFor','invoice','firsts','order','tables');
